def split_bill(total_cents: int, weights: list[int]) -> list[int]:
    if any(w < 0 for w in weights):
        raise ValueError("weights must be non-negative")

    if not weights:
        return []

    total_weight = sum(weights)
    if total_weight == 0:
        raise ValueError("weights sum must be positive")

    base = [(total_cents * w) // total_weight for w in weights]
    remainder = total_cents - sum(base)

    fractional_parts = [(total_cents * weights[i]) % total_weight for i in range(len(weights))]

    for i in sorted(range(len(weights)), key=lambda i: (-fractional_parts[i], i)):
        if remainder <= 0:
            break
        base[i] += 1
        remainder -= 1

    return base
```

