def parse_duration(s: str) -> int:
    if not isinstance(s, str):
        return -1

    s = s.strip()
    if not s:
        return -1

    units = {"d": 86400, "h": 3600, "m": 60, "s": 1}
    order = {"d": 0, "h": 1, "m": 2, "s": 3}

    total = 0
    i = 0
    n = len(s)
    last = -1

    while i < n:
        while i < n and s[i] == " ":
            i += 1

        if i >= n:
            break

        if not ("0" <= s[i] <= "9"):
            return -1

        start = i
        while i < n and "0" <= s[i] <= "9":
            i += 1

        if i >= n:
            return -1

        unit = s[i]
        if unit not in units:
            return -1

        idx = order[unit]
        if idx <= last:
            return -1

        last = idx
        total += int(s[start:i]) * units[unit]
        i += 1

    return total
