def compare_versions(a: str, b: str) -> int:
    def _strip_prefix(s: str) -> str:
        if s and s[0] in ("v", "V"):
            return s[1:]
        return s

    def _parse(s: str):
        s = _strip_prefix(s)

        if "-" in s:
            body, tag = s.split("-", 1)
            tag = tag if tag else None
        else:
            body = s
            tag = None

        if not body:
            parts = [0]
        else:
            parts = [int(x) for x in body.split(".")]

        return parts, tag

    a_parts, a_tag = _parse(a)
    b_parts, b_tag = _parse(b)

    max_len = max(len(a_parts), len(b_parts))
    for i in range(max_len):
        av = a_parts[i] if i < len(a_parts) else 0
        bv = b_parts[i] if i < len(b_parts) else 0

        if av > bv:
            return 1
        if av < bv:
            return -1

    if a_tag is None and b_tag is None:
        return 0
    if a_tag is None:
        return 1
    if b_tag is None:
        return -1

    if a_tag > b_tag:
        return 1
    if a_tag < b_tag:
        return -1

    return 0
